      "item": "i01",
      "choice": "v1",
      "reason": "Le point 1.10, page 1, prévoit le second projet SP-2026-14 concernant le zonage, dont les dispositions sur les contributions pour parcs sont précisées page 12."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "Le point 1.11, page 1, inscrit explicitement le second projet SP-2026-15 concernant la grille des spécifications de la zone V-802."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "Le règlement 1470-2026 figure au point 1.12, page 1, et son calendrier page 17 confirme une adoption prévue le 2 juin 2026, sans attester une décision acquise."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "Le règlement de zonage 1471-2026 est inscrit au point 1.13, page 1, avec une adoption prévue le 2 juin 2026 dans le calendrier de la page 28."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "Le point 1.14, page 1, vise le règlement 1472-2026 relatif aux permis et certificats, dont l'adoption est prévue le 2 juin 2026 selon la page 41."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "Le point 1.15, page 1, vise le règlement 1473-2026 modifiant la réglementation des PIIA, avec une adoption prévue le 2 juin 2026 indiquée page 42."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "Le point 1.16, page 2, prévoit explicitement une demande de prolongation du délai de conformité aux normes de lotissement agricole découlant du règlement 399-25."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "Le point 1.20, page 2, prévoit une demande de modification du règlement 188-07 pour réduire l'aire d'affectation Conservation, sans constater l'adoption de cette modification."
    },
    {
      "item": "i09",
      "choice": "absent",
      "reason": "Le point 6.3, page 2, inscrit bien la servitude sur une parcelle du lot 4 037 185, mais n'annonce explicitement ni adoption ni autorisation, de sorte que l'étape « adoption » proposée n'est pas attestée."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "Le point 9.1, page 3, inscrit la demande de PIIA du 799, rue de New Glasgow comme point prévu, sans attester son approbation."
    },
    {
      "item": "i11",
      "choice": "v1",
      "reason": "Le point 9.2, page 3, prévoit l'examen d'une dérogation mineure au 537, chemin de l'Achigan Ouest, sans décision acquise."
    },
    {
      "item": "i12",
      "choice": "v1",
      "reason": "Le point 9.3, page 3, inscrit la dérogation mineure du 318-318 A, chemin Abercrombie, ce qui atteste une unité prévue et non une autorisation accordée."
    }
  ]
}
